"use client";

import { useState } from "react";
import { Header } from "@/components/sql-assistant/header";
import { QueryInput } from "@/components/sql-assistant/query-input";
import { SqlOutput } from "@/components/sql-assistant/sql-output";
import { ResultsDisplay } from "@/components/sql-assistant/results-display";
import { ExamplePrompts } from "@/components/sql-assistant/example-prompts";
import { LoadingSkeleton } from "@/components/sql-assistant/loading-skeleton";

const API_URL =
  process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:3001";

type ApiResponse = {
  // The SQL the backend actually executed
  query?: string;
  sql?: string;
  executed_query?: string;
  // The textual response / result summary
  response?: string;
  result?: string;
  results?: string;
  text?: string;
  // Anything else gets stringified as a fallback
  [key: string]: unknown;
};

async function fetchSqlResponse(
  query: string,
  signal?: AbortSignal,
): Promise<{ sql: string; results: string }> {
  const res = await fetch(`${API_URL}/query`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ query }),
    signal,
  });

  if (!res.ok) {
    const errText = await res.text().catch(() => "");
    throw new Error(
      `Request failed (${res.status} ${res.statusText})${
        errText ? `: ${errText}` : ""
      }`,
    );
  }

  // Try JSON first; fall back to plain text.
  const contentType = res.headers.get("content-type") ?? "";
  if (contentType.includes("application/json")) {
    const data = (await res.json()) as ApiResponse;
    const sql =
      data.query ??
      data.sql ??
      data.executed_query ??
      "";
    const results =
      data.response ??
      data.result ??
      data.results ??
      data.text ??
      "";
    return {
      sql: typeof sql === "string" ? sql : JSON.stringify(sql, null, 2),
      results:
        typeof results === "string"
          ? results
          : JSON.stringify(results, null, 2),
    };
  }

  const text = await res.text();
  return { sql: "", results: text };
}

export default function SqlAssistantPage() {
  const [query, setQuery] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [response, setResponse] = useState<{
    sql: string;
    results: string;
  } | null>(null);

  const handleSubmit = async () => {
    if (!query.trim()) return;

    setIsLoading(true);
    setError(null);
    setResponse(null);

    const controller = new AbortController();
    try {
      const result = await fetchSqlResponse(query, controller.signal);
      setResponse(result);
    } catch (err) {
      const message =
        err instanceof Error ? err.message : "Unexpected error";
      console.error("Error fetching SQL response:", err);
      setError(message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleExampleSelect = (prompt: string) => {
    setQuery(prompt);
  };

  return (
    <div className="min-h-screen bg-background">
      <Header />
      <main className="max-w-5xl mx-auto px-4 sm:px-6 py-8 sm:py-12">
        <div className="mb-8 sm:mb-12 text-center">
          <h2 className="text-2xl sm:text-3xl font-bold text-foreground mb-3 text-balance">
            Transform Natural Language into SQL
          </h2>
          <p className="text-muted-foreground text-sm sm:text-base max-w-2xl mx-auto text-pretty">
            Describe what data you need in plain English, and let AI generate
            optimized SQL queries for your database.
          </p>
        </div>

        <QueryInput
          query={query}
          setQuery={setQuery}
          onSubmit={handleSubmit}
          isLoading={isLoading}
        />

        {isLoading && (
          <div className="mt-6 sm:mt-8">
            <LoadingSkeleton />
          </div>
        )}

        {error && !isLoading && (
          <div className="mt-6 sm:mt-8 rounded-xl border border-red-500/40 bg-red-500/5 px-4 py-3 text-sm text-red-400">
            <span className="font-medium">Request failed:</span> {error}
          </div>
        )}

        {response && !isLoading && (
          <div className="mt-6 sm:mt-8 space-y-4 sm:space-y-6">
            {response.sql && <SqlOutput sql={response.sql} />}
            <ResultsDisplay results={response.results} />
          </div>
        )}

        <ExamplePrompts onSelect={handleExampleSelect} disabled={isLoading} />
      </main>
    </div>
  );
}
